/*
 * High-performance portfolio calculations using C extension
 *
 * Implements the optimized C functions below.
 * Uses NumPy C API for zero-copy array access.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_in, *cov_in;

    // Parse NumPy arrays
    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_in,
                                       &PyArray_Type, &cov_in))
        return NULL;

    // Ensure we have contiguous float64 arrays (no copy if already so)
    PyObject *weights_obj = PyArray_FROM_OTF((PyObject *)weights_in, NPY_DOUBLE,
                                             NPY_ARRAY_C_CONTIGUOUS);
    PyObject *cov_obj = PyArray_FROM_OTF((PyObject *)cov_in, NPY_DOUBLE,
                                         NPY_ARRAY_C_CONTIGUOUS);
    if (!weights_obj || !cov_obj) {
        Py_XDECREF(weights_obj);
        Py_XDECREF(cov_obj);
        return NULL;
    }

    PyArrayObject *weights = (PyArrayObject *)weights_obj;
    PyArrayObject *cov = (PyArrayObject *)cov_obj;

    npy_intp n = PyArray_DIM(weights, 0);
    const double *w = (const double *)PyArray_DATA(weights);
    const double *cov_data = (const double *)PyArray_DATA(cov);

    // risk = sqrt(x^T S x). Compute in same order as the Python baseline:
    // temp[i] = sum_j cov[i][j] * w[j];  risk_squared = sum_i w[i] * temp[i]
    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; i++) {
        const double *row = cov_data + i * n;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; j++) {
            row_sum += row[j] * w[j];
        }
        risk_squared += w[i] * row_sum;
    }

    double risk = sqrt(risk_squared);

    Py_DECREF(weights_obj);
    Py_DECREF(cov_obj);
    return PyFloat_FromDouble(risk);
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_in, *returns_in;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_in,
                                       &PyArray_Type, &returns_in))
        return NULL;

    PyObject *weights_obj = PyArray_FROM_OTF((PyObject *)weights_in, NPY_DOUBLE,
                                             NPY_ARRAY_C_CONTIGUOUS);
    PyObject *returns_obj = PyArray_FROM_OTF((PyObject *)returns_in, NPY_DOUBLE,
                                             NPY_ARRAY_C_CONTIGUOUS);
    if (!weights_obj || !returns_obj) {
        Py_XDECREF(weights_obj);
        Py_XDECREF(returns_obj);
        return NULL;
    }

    PyArrayObject *weights = (PyArrayObject *)weights_obj;
    PyArrayObject *returns = (PyArrayObject *)returns_obj;

    npy_intp n = PyArray_DIM(weights, 0);
    const double *w = (const double *)PyArray_DATA(weights);
    const double *r = (const double *)PyArray_DATA(returns);

    // return = w^T * r
