/*
 * High-performance portfolio calculations using a C extension.
 *
 * The benchmark passes plain Python sequences:
 *   - weights : list of floats
 *   - cov     : list of lists of floats (the covariance matrix)
 *   - returns : list of floats
 *
 * Reading a large list-of-lists through NumPy's generic list->array
 * conversion is expensive (pure-Python nested iteration).  Instead we read
 * the Python sequences directly in C and compute in a single fused pass,
 * which is dramatically faster.  A NumPy-array fast path is kept for
 * robustness when arrays are passed in directly.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/* Extract a double from a Python object.  Floats are the common case and are
 * handled without a function call; anything else falls back to the general
 * converter. */
static inline double get_double(PyObject *o) {
    if (PyFloat_Check(o)) {
        return PyFloat_AS_DOUBLE(o);
    }
    return PyFloat_AsDouble(o);
}

/* Materialise a 1-D sequence (Python list or 1-D numpy array) into a freshly
 * malloc'd double array.  Returns NULL on error (exception set). */
static double *read_vector(const PyObject *obj, npy_intp *out_n) {
    npy_intp n = 0;
    double *v = NULL;

    if (PyList_Check(obj)) {
        n = PyList_GET_SIZE(obj);
    } else if (PyArray_Check(obj)) {
        n = PyArray_DIM((PyArrayObject *)obj, 0);
    } else {
        PyErr_SetString(PyExc_TypeError,
                        "expected a list or 1-D numpy array");
        return NULL;
    }

    v = (double *)malloc((size_t)(n > 0 ? n : 1) * sizeof(double));
    if (!v) {
        PyErr_NoMemory();
        return NULL;
    }

    if (PyList_Check(obj)) {
        for (npy_intp i = 0; i < n; i++) {
            double d = get_double(PyList_GET_ITEM((PyObject *)obj, i));
            if (d == -1.0 && PyErr_Occurred()) { free(v); return NULL; }
            v[i] = d;
        }
    } else {
        PyObject *tmp = PyArray_FROM_OTF((PyObject *)obj, NPY_DOUBLE,
                                         NPY_ARRAY_C_CONTIGUOUS);
        if (!tmp) { free(v); return NULL; }
        const double *src = (const double *)PyArray_DATA((PyArrayObject *)tmp);
        for (npy_intp i = 0; i < n; i++) v[i] = src[i];
        Py_DECREF(tmp);
    }

    *out_n = n;
    return v;
}

static PyObject *portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    npy_intp n = 0;
    double *w = read_vector(weights_obj, &n);
    if (!w)
        return NULL;

    double risk_squared = 0.0;
    int status = 0;

    if (PyList_Check(cov_obj)) {
        // Fused read + compute in the baseline summation order:
        //   row_sum = sum_j cov[i][j] * w[j];  risk_squared += w[i] * row_sum
        if ((npy_intp)PyList_GET_SIZE(cov_obj) != n) {
            PyErr_SetString(PyExc_ValueError,
                            "cov row count does not match weight length");
            status = 1;
        } else {
            for (npy_intp i = 0; i < n && !status; i++) {
                PyObject *row = PyList_GET_ITEM(cov_obj, i);
                if (!PyList_Check(row)) {
                    PyErr_SetString(PyExc_TypeError,
                                    "cov must be a list of lists of numbers");
                    status = 1;
                    break;
                }
                double row_sum = 0.0;
                for (npy_intp j = 0; j < n; j++) {
                    double d = get_double(PyList_GET_ITEM(row, j));
                    if (d == -1.0 && PyErr_Occurred()) { status = 1; break; }
                    row_sum += d * w[j];
                }
                risk_squared += w[i] * row_sum;
            }
        }
    } else if (PyArray_Check(cov_obj)) {
        PyObject *tmp = PyArray_FROM_OTF((PyObject *)cov_obj, NPY_DOUBLE,
                                         NPY_ARRAY_C_CONTIGUOUS);
        if (!tmp) {
            status = 1;
        } else {
            const double *cov_data =
                (const double *)PyArray_DATA((PyArrayObject *)tmp);
            for (npy_intp i = 0; i < n; i++) {
                const double *row = cov_data + i * n;
                double row_sum = 0.0;
                for (npy_intp j = 0; j < n; j++) row_sum += row[j] * w[j];
                risk_squared += w[i] * row_sum;
            }
            Py_DECREF(tmp);
        }
    } else {
        PyErr_SetString(PyExc_TypeError,
                        "cov must be a list of lists or a 2-D numpy array");
        status = 1;
    }

    free(w);
    if (status)
        return NULL;
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject *portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    npy_intp nw = 0, nr = 0;
    double *w = read_vector(weights_obj, &nw);
    if (!w)
        return NULL;
    double *r = read_vector(returns_obj, &nr);
    if (!r) {
        free(w);
        return NULL;
    }

    npy_intp n = (nw < nr) ? nw : nr;
    double total = 0.0;
    for (npy_intp i = 0; i < n; i++) {
        total += w[i] * r[i];
    }

    free(w);
    free(r);
    return PyFloat_FromDouble(total);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  // Initialize NumPy C API
    return PyModule_Create(&moduledef);
}
