>         PyErr_SetString(PyExc_TypeError,
>                         "cov must be a list of lists or a 2-D numpy array");
>         status = 1;
>     }
>
>     free(w);
>     if (status)
>         return NULL;
>     return PyFloat_FromDouble(sqrt(risk_squared));
> }
